args.command:
awk 'BEGIN{
  srand(42);
  lower="abcdefghijklmnopqrstuvwxyz";
  mixed="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_";
  ntail=split("s ss es ies ys x ch sh us is um on a _s _ies S ES", tails, " ");
  # set 1: pure lowercase random
  for(i=0;i<900;i++){
    n=int(rand()*13); w="";
    for(j=0;j<n;j++){ k=int(rand()*26)+1; w=w substr(lower,k,1); }
    print w;
  }
  # set 2: mixed charset
  lm=length(mixed);
  for(i=0;i<700;i++){
    n=int(rand()*13); w="";
    for(j=0;j<n;j++){ k=int(rand()*lm)+1; w=w substr(mixed,k,1); }
    print w;
  }
  # set 3: plural/classify-biased
  bias="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_";
  lb=length(bias);
  for(i=0;i<500;i++){
    n=int(rand()*9); w="";
    for(j=0;j<n;j++){ k=int(rand()*lb)+1; w=w substr(bias,k,1); }
    t=tails[int(rand()*ntail)+1];
    print w t;
  }
}' > /tmp/words_random.txt
wc -l /tmp/words_random.txt
cat /tmp/words_pos3.txt /tmp/words_utf8.txt /tmp/words_random.txt > /tmp/all_words.txt
wc -l /tmp/all_words.txt
# sanity: show a few random lines including empty ones
sed -n '265,275p' /tmp/all_words.txt | cat -A | head
